from opentrons import protocol_api
requirements = {"robotType": "OT-2", "apiLevel": "2.19"}
metadata = {"protocolName": "t2"}
def run(ctx: protocol_api.ProtocolContext):
    tips20 = ctx.load_labware("opentrons_96_tiprack_20ul", 1)
    tips300 = ctx.load_labware("opentrons_96_tiprack_300ul", 2)
    temp = ctx.load_module("temperature module gen2", 3)
    block = temp.load_labware("opentrons_96_aluminumblock_nest_wellplate_100ul")
    mag = ctx.load_module("magnetic module gen2", 6)
    deep = mag.load_labware("nest_96_wellplate_2ml_deep")
    res = ctx.load_labware("nest_12_reservoir_15ml", 5)
    tubes = ctx.load_labware("opentrons_24_tuberack_nest_1.5ml_snapcap", 4)
    p20 = ctx.load_instrument("p20_single_gen2", "left", tip_racks=[tips20])
    p300m = ctx.load_instrument("p300_multi_gen2", "right", tip_racks=[tips300])
    ctx.comment("hello")
    p20.pick_up_tip()
    p20.aspirate(5, tubes["A1"])
    p20.dispense(5, block["A1"])
    p20.mix(3, 10, block["A1"])
    p20.blow_out(block["A1"].top())
    p20.touch_tip()
    p20.drop_tip()
    temp.set_temperature(4)
    temp.set_temperature(42)
    ctx.delay(seconds=45)
    temp.deactivate()
    mag.engage()
    ctx.delay(minutes=2, msg="settle")
    mag.disengage()
    p300m.transfer(100, res["A1"], deep.rows()[0][0], mix_after=(3, 50))
    p20.distribute(5, tubes["A2"], [block["A2"], block["A3"]], disposal_volume=2)
    ctx.pause("human step")
    ctx.home()
